import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT || 4173);
const apiBase = process.env.CG_API_BASE || 'https://api.crypto.games/v1';
const liveEnabled = process.env.ENABLE_LIVE_BETTING !== 'false';
const maxLiveBet = Number(process.env.MAX_LIVE_BET || 0);
const maxSessionLoss = Number(process.env.MAX_SESSION_LOSS || 0);
const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
const sessions = new Map();

function json(res, status, data) { res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }); res.end(JSON.stringify(data)); }
function parseBody(req) { return new Promise((resolve, reject) => { let raw = ''; req.on('data', c => { raw += c; if (raw.length > 30_000) req.destroy(); }); req.on('end', () => { try { resolve(raw ? JSON.parse(raw) : {}); } catch { reject(new Error('Invalid JSON')); } }); req.on('error', reject); }); }
function cookie(req, name) { return (req.headers.cookie || '').split(';').map(v => v.trim()).find(v => v.startsWith(`${name}=`))?.slice(name.length + 1); }
function auth(req, res) { const s = sessions.get(cookie(req, 'df_session')); if (!s) { json(res, 401, { error: 'Login API diperlukan.' }); return null; } return s; }
async function cg(endpoint, options = {}) { let lastError; for (let attempt = 0; attempt < 4; attempt++) { try { const r = await fetch(`${apiBase}${endpoint}`, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } }); const text = await r.text(); let data; try { data = JSON.parse(text); } catch { data = { raw: text }; } if (!r.ok) { const error = new Error(`Crypto.Games HTTP ${r.status}${data?.Message ? `: ${data.Message}` : data?.Error ? `: ${data.Error}` : ''}`); error.status = r.status; error.details = data; if (![502,503,504].includes(r.status) || attempt === 3) throw error; lastError = error; } else return data; } catch (e) { lastError = e; if (!/Crypto\.Games HTTP (502|503|504)|fetch failed|timed out|UND_ERR/i.test(e.message) || attempt === 3) throw e; } await new Promise(resolve => setTimeout(resolve, 750 * 2 ** attempt)); } throw lastError; }

const strategyProfiles = {
  safe: { label: 'STEADY EDGE', mode: 'flat', basePct: .15, maxBetPct: .75, payout: 1.35, under: true, stopLossPct: 2, takeProfitPct: 3, maxRolls: 80, delayMs: 4000, lossMult: 1, lossReset: 1, maxLossStreak: 5, maxErrors: 3 },
  hybrid: { label: 'HYBRID GUARD', mode: 'capped-recovery', basePct: .2, maxBetPct: 1.25, payout: 1.5, under: true, stopLossPct: 3, takeProfitPct: 4, maxRolls: 100, delayMs: 3000, lossMult: 1.25, lossReset: 3, maxLossStreak: 5, maxErrors: 3 },
  fibonacci: { label: 'FIBO CONTROL', mode: 'bounded-ladder', basePct: .1, maxBetPct: .75, payout: 1.65, under: false, stopLossPct: 2.5, takeProfitPct: 4, maxRolls: 80, delayMs: 4500, lossMult: 1, lossReset: 6, maxLossStreak: 6, maxErrors: 3 },
  flat: { label: 'FLAT EDGE', mode: 'flat', basePct: 0.25, maxBetPct: 1.0, payout: 2.0, under: true, stopLossPct: 5, takeProfitPct: 2, maxRolls: 5000, delayMs: 100, lossMult: 1, lossReset: 1, maxLossStreak: 15, maxErrors: 3, lockBreakevenAfterPct: 1 }
};

function activeProfile(strategy) { return strategyProfiles[strategy] || strategyProfiles.safe; }

function publicSession(s) {
  const pnlAmount = Number(s.bot.stats?.profit || 0);
  const pnlPct = s.startedBalance > 0 ? (pnlAmount / s.startedBalance) * 100 : 0;
  const cooldownRemaining = s.bot.cooldownUntil ? Math.max(0, s.bot.cooldownUntil - Date.now()) : 0;
  return {
    coin: s.coin,
    balance: s.balance,
    settings: s.settings,
    risk: {
      sessionLoss: s.sessionLoss,
      rolls: Number(s.bot.stats?.rolls || 0),
      startedBalance: s.startedBalance,
      pnlAmount,
      pnlPct,
      floorBalance: s.bot.floorBalance ?? null,
      locked: s.bot.locked ?? false
    },
    bot: {
      running: s.bot.running,
      paused: s.bot.paused,
      cooldownRemaining,
      sessions: s.bot.sessions,
      config: s.bot.config,
      stats: s.bot.stats,
      stopReason: s.bot.stopReason
    }
  };
}

function clearBot(s, reason = 'Dihentikan manual oleh pengguna.') {
  if (s.bot.timer) clearTimeout(s.bot.timer);
  s.bot.timer = null;
  s.bot.running = false;
  s.bot.paused = false;
  s.bot.cooldownUntil = 0;
  s.bot.runId++;
  s.bot.stopReason = reason;
}

function apiSetting(s, ...keys) {
  for (const key of keys) {
    const value = Number(s.settings?.[key]);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function validateBetAgainstSettings(s, bet, payout) {
  const minBet = apiSetting(s, 'MinBet', 'MinBetAmount');
  const maxBet = apiSetting(s, 'MaxBet', 'MaxBetAmount');
  const minPayout = apiSetting(s, 'MinPayout');
  const maxPayout = apiSetting(s, 'MaxPayout');
  if (minBet !== null && bet < minBet) return `Bet ${bet.toFixed(8)} di bawah minimum coin ${minBet}.`;
  if (maxBet !== null && bet > maxBet) return `Bet ${bet.toFixed(8)} di atas maksimum coin ${maxBet}.`;
  if (minPayout !== null && payout < minPayout) return `Payout ${payout}x di bawah minimum coin ${minPayout}x.`;
  if (maxPayout !== null && payout > maxPayout) return `Payout ${payout}x di atas maksimum coin ${maxPayout}x.`;
  return null;
}

function nextBet(s) {
  const c = s.bot.config;
  const base = s.startedBalance * c.basePct / 100;
  const lossStep = s.bot.stats.lossStreak;
  let bet = base;
  if (c.mode === 'capped-recovery') bet = lossStep >= c.lossReset ? base : base * Math.pow(c.lossMult, lossStep);
  if (c.mode === 'bounded-ladder') {
    const fib = [1, 1, 2, 3, 5, 8, 13];
    bet = base * fib[Math.min(lossStep, c.lossReset)];
  }
  // Flat mode: bet tetap, tidak ada kenaikan pasca-kalah
  // Bulatkan ke bawah ke satuan minbet
  const minBet = apiSetting(s, 'MinBet', 'MinBetAmount');
  if (minBet !== null && minBet > 0) bet = Math.floor(bet / minBet) * minBet;
  return Math.min(bet, s.startedBalance * c.maxBetPct / 100, maxLiveBet || Infinity);
}

function rollValue(result) {
  const value = result?.Result ?? result?.result ?? result?.Roll ?? result?.roll ?? result?.Number ?? result?.number ?? result?.Rolled ?? result?.rolled ?? null;
  if (value === null || value === undefined || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : String(value);
}

function rollDirection(result, roll, under) {
  const value = result?.HiLow ?? result?.HighLow ?? result?.hiLow ?? result?.highLow ?? result?.Direction ?? result?.direction ?? result?.UnderOver ?? null;
  if (value !== null && value !== undefined && value !== '') return String(value).toUpperCase();
  if (typeof roll === 'number') return roll < 50 ? 'LOW' : 'HIGH';
  return under ? 'LOW' : 'HIGH';
}

function pauseForTarget(s, runId) {
  const c = s.bot.config;
  const cooldownMs = (60 + Math.floor(Math.random() * 541)) * 1000;
  s.bot.paused = true;
  s.bot.sessions++;
  s.bot.cooldownUntil = Date.now() + cooldownMs;
  s.bot.cycleProfit = 0;
  s.bot.stats.lossStreak = 0;
  s.bot.stopReason = `TARGET PROFIT TERCAPAI: +${c.takeProfitPct}% · pause ${Math.round(cooldownMs / 60000)} menit · session berikutnya segera dimulai.`;
  if (s.bot.timer) clearTimeout(s.bot.timer);
  s.bot.timer = setTimeout(() => {
    if (!s.bot.running || s.bot.runId !== runId) return;
    s.bot.paused = false;
    s.bot.cooldownUntil = 0;
    s.bot.stopReason = `Session ${s.bot.sessions + 1} dimulai setelah cooldown target profit.`;
    void botTick(s, runId);
  }, cooldownMs);
}

async function botTick(s, runId = s.bot.runId) {
  if (!s.bot.running || s.bot.runId !== runId || s.bot.paused) return;
  const c = s.bot.config;
  if (s.bot.stats.rolls >= c.maxRolls) {
    clearBot(s, `Selesai: mencapai batas ${c.maxRolls} rolls.`);
    return;
  }
  const netPnl = Number(s.bot.stats.profit || 0);
  const currentBalance = s.balance?.Balance ?? s.startedBalance;
  // Cek floor balance: stop-loss awal atau breakeven setelah lock
  if (currentBalance <= s.bot.floorBalance) {
    const floorPct = ((s.bot.floorBalance / s.startedBalance - 1) * 100).toFixed(2);
    clearBot(s, `STOP: saldo mencapai floor ${floorPct}% dari bankroll awal.`);
    return;
  }
  // Lock breakeven: setelah profit mencapai lockBreakevenAfterPct%, floor dinaikkan ke bankroll awal
  if (!s.bot.locked && c.lockBreakevenAfterPct > 0 && netPnl >= s.startedBalance * c.lockBreakevenAfterPct / 100) {
    s.bot.floorBalance = s.startedBalance;
    s.bot.locked = true;
    s.bot.stopReason = `LOCK BREAK EVEN: profit +${c.lockBreakevenAfterPct}% tercapai, floor dikunci ke bankroll awal.`;
  }
  if (c.takeProfitPct > 0 && s.bot.cycleProfit >= s.startedBalance * c.takeProfitPct / 100) {
    pauseForTarget(s, runId);
    return;
  }
  if (s.bot.stats.lossStreak >= c.maxLossStreak) {
    clearBot(s, `STOP: ${c.maxLossStreak} kekalahan beruntun mencapai batas strategi.`);
    return;
  }
  const bet = nextBet(s);
  if (!Number.isFinite(bet) || bet <= 0) {
    clearBot(s, 'Berhenti: bet amount tidak valid atau saldo tidak mencukupi.');
    return;
  }
  const betValidation = validateBetAgainstSettings(s, bet, c.payout);
  if (betValidation) {
    clearBot(s, `API menolak konfigurasi taruhan: ${betValidation}`);
    return;
  }
  try {
    const result = await cg(`/placebet/${encodeURIComponent(s.coin)}/${encodeURIComponent(s.apiKey)}`, {
      method: 'POST',
      body: JSON.stringify({ Bet: Number(bet.toFixed(8)), Payout: c.payout, UnderOver: c.under, ClientSeed: crypto.randomBytes(16).toString('hex') })
    });
    const profit = Number(result.Profit || 0);
    const st = s.bot.stats;
    st.transientErrors = 0;
    st.errors = 0;
    st.lastError = null;
    st.rolls++;
    st.profit += profit;
    s.bot.cycleProfit += profit;
    st.wins += profit > 0 ? 1 : 0;
    st.losses += profit > 0 ? 0 : 1;
    st.lossStreak = profit > 0 ? 0 : st.lossStreak + 1;
    st.winStreak = profit > 0 ? st.winStreak + 1 : 0;
    st.maxLossStreak = Math.max(st.maxLossStreak, st.lossStreak);
    st.maxWinStreak = Math.max(st.maxWinStreak, st.winStreak);
    st.wagered += bet;
    s.sessionLoss += Math.max(0, -profit);
    const roll = rollValue(result);
    const highLow = rollDirection(result, roll, c.under);
    if (result.Balance !== undefined || result.balance !== undefined) s.balance = { ...s.balance, Balance: result.Balance ?? result.balance };
    st.last = { profit, bet, balance: s.balance?.Balance ?? null, result: roll, hiLow: highLow, at: Date.now() };
  } catch (e) {
    const transient = /Crypto\.Games HTTP (502|503|504)|fetch failed|timed out|UND_ERR/i.test(e.message);
    s.bot.stats.lastError = e.message;
    if (transient) {
      s.bot.stats.transientErrors = (s.bot.stats.transientErrors || 0) + 1;
      s.bot.stats.errors = s.bot.stats.transientErrors;
      const retryMs = Math.min(60000, c.delayMs * Math.pow(2, Math.min(s.bot.stats.transientErrors - 1, 4)));
      s.bot.stopReason = `API sementara gagal (${e.message}) · retry dalam ${Math.ceil(retryMs / 1000)} detik.`;
      if (s.bot.running && s.bot.runId === runId && !s.bot.paused) s.bot.timer = setTimeout(() => void botTick(s, runId), retryMs);
      return;
    }
    if (e.status === 422) {
      clearBot(s, `API menolak taruhan (422): ${e.message.replace('Crypto.Games HTTP 422', '').replace(/^:\s*/, '') || 'parameter taruhan tidak valid.'}`);
    } else {
      s.bot.stats.errors++;
      if (s.bot.stats.errors >= c.maxErrors) clearBot(s, `Berhenti: ${s.bot.stats.errors} error API berturut-turut (${e.message}).`);
    }

    }
  }
  if (s.bot.running && s.bot.runId === runId && !s.bot.paused) s.bot.timer = setTimeout(() => void botTick(s, runId), c.delayMs);
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
  try {
    if (req.method === 'GET' && url.pathname === '/api/status') return json(res, 200, { liveOnly: true, liveEnabled, authenticated: sessions.has(cookie(req, 'df_session')), maxLiveBet: maxLiveBet || null, maxSessionLoss: maxSessionLoss || null });
    if (req.method === 'POST' && url.pathname === '/api/login') {
      if (!liveEnabled) return json(res, 403, { error: 'Live mode disabled.' });
      const input = await parseBody(req);
      const apiKey = String(input.apiKey || '').trim();
      const coin = String(input.coin || 'PLAY').trim().toUpperCase();
      if (!apiKey || apiKey.length < 8) return json(res, 400, { error: 'API key tidak valid.' });
      const settings = await cg(`/settings/${encodeURIComponent(coin)}`);
      const balance = await cg(`/balance/${encodeURIComponent(coin)}/${encodeURIComponent(apiKey)}`);
      const token = crypto.randomBytes(32).toString('hex');
      const s = {
        apiKey,
        coin,
        settings,
        balance,
        startedBalance: Number(balance.Balance),
        sessionLoss: 0,
        rolls: 0,
        bot: {
          running: false,
          paused: false,
          cooldownUntil: 0,
          sessions: 0,
          cycleProfit: 0,
          timer: null,
          runId: 0,
          stopReason: 'Belum ada session bot.',
          config: null,
          stats: { rolls: 0, wins: 0, losses: 0, profit: 0, wagered: 0, lossStreak: 0, winStreak: 0, maxLossStreak: 0, maxWinStreak: 0, errors: 0, last: null }
        }
      };
      sessions.set(token, s);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Set-Cookie': `df_session=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=3600`, 'Cache-Control': 'no-store' });
      return res.end(JSON.stringify(publicSession(s)));
    }
    if (req.method === 'POST' && url.pathname === '/api/logout') {
      const token = cookie(req, 'df_session');
      const s = sessions.get(token);
      if (s) clearBot(s);
      sessions.delete(token);
      res.writeHead(200, { 'Set-Cookie': 'df_session=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0' });
      return res.end('{}');
    }
    if (req.method === 'GET' && url.pathname === '/api/account') {
      const s = auth(req, res);
      if (!s) return;
      try { s.balance = await cg(`/balance/${encodeURIComponent(s.coin)}/${encodeURIComponent(s.apiKey)}`); } catch {}
      return json(res, 200, publicSession(s));
    }
    if (req.method === 'POST' && url.pathname === '/api/coin') {
      const s = auth(req, res);
      if (!s) return;
      if (s.bot.running) return json(res, 409, { error: 'Hentikan bot sebelum mengganti coin.' });
      const i = await parseBody(req);
      const coin = String(i.coin || '').trim().toUpperCase();
      if (!/^[A-Z0-9]{2,12}$/.test(coin)) return json(res, 400, { error: 'Coin tidak valid.' });
      const settings = await cg(`/settings/${encodeURIComponent(coin)}`);
      const balance = await cg(`/balance/${encodeURIComponent(coin)}/${encodeURIComponent(s.apiKey)}`);
      s.coin = coin;
      s.settings = settings;
      s.balance = balance;
      s.startedBalance = Number(balance.Balance);
      s.sessionLoss = 0;
      s.rolls = 0;
      return json(res, 200, publicSession(s));
    }
    if (req.method === 'POST' && url.pathname === '/api/live/start') {
      const s = auth(req, res);
      if (!s) return;
      if (s.bot.running) return json(res, 409, { error: 'Bot sudah berjalan.' });
      const i = await parseBody(req);
      const p = activeProfile(String(i.strategy || 'safe'));
      const c = {
        ...p,
        strategy: String(i.strategy || 'safe'),
        basePct: Math.min(p.maxBetPct, Number.isFinite(Number(i.maxBetPct)) ? Number(i.maxBetPct) : p.maxBetPct, Math.max(.05, Number.isFinite(Number(i.basePct)) ? Number(i.basePct) : p.basePct)),
        maxBetPct: Math.min(p.maxBetPct, Math.max(.05, Number.isFinite(Number(i.maxBetPct)) ? Number(i.maxBetPct) : p.maxBetPct)),
        payout: p.payout,
        under: p.under,
        stopLossPct: Math.min(50, Math.max(.1, Number.isFinite(Number(i.stopLossPct)) ? Number(i.stopLossPct) : p.stopLossPct)),
        takeProfitPct: Math.min(100, Math.max(0, Number.isFinite(Number(i.takeProfitPct)) ? Number(i.takeProfitPct) : p.takeProfitPct)),
        maxRolls: Math.min(10000, Math.max(1, Number.isFinite(Number(i.maxRolls)) ? Number(i.maxRolls) : p.maxRolls)),
        delayMs: Math.max(100, Math.min(60000, Number.isFinite(Number(i.delayMs)) ? Number(i.delayMs) : p.delayMs)),
        lossMult: p.lossMult,
        lossReset: p.lossReset,
        maxLossStreak: p.maxLossStreak,
        maxErrors: p.maxErrors
      };
      if (maxSessionLoss > 0) c.stopLossPct = Math.min(c.stopLossPct, maxSessionLoss / s.startedBalance * 100);
      s.bot.config = c;
      s.sessionLoss = 0;
      s.rolls = 0;
      s.bot.paused = false;
      s.bot.cooldownUntil = 0;
      s.bot.sessions = 1;
      s.bot.cycleProfit = 0;
      s.bot.stats = { rolls: 0, wins: 0, losses: 0, profit: 0, wagered: 0, lossStreak: 0, winStreak: 0, maxLossStreak: 0, maxWinStreak: 0, errors: 0, transientErrors: 0, last: null, lastError: null };
      s.bot.floorBalance = s.startedBalance * (1 - c.stopLossPct / 100);
      s.bot.locked = false;
      s.bot.running = true;
      s.bot.stopReason = `Session aktif: ${c.strategy.toUpperCase()} · cooldown ${(c.delayMs / 1000).toFixed(1)}s.`;
      s.bot.runId++;
      const runId = s.bot.runId;
      void botTick(s, runId);
      return json(res, 200, publicSession(s));
    }
    if (req.method === 'POST' && url.pathname === '/api/live/stop') {
      const s = auth(req, res);
      if (!s) return;
      clearBot(s);
      return json(res, 200, publicSession(s));
    }
    if (req.method === 'POST' && url.pathname === '/api/live/bet') {
      const s = auth(req, res);
      if (!s) return;
      const i = await parseBody(req);
      if (s.bot.running) return json(res, 409, { error: 'Stop bot otomatis sebelum manual roll.' });
      const bet = Number(i.Bet), payout = Number(i.Payout);
      if (!Number.isFinite(bet) || bet <= 0 || !Number.isFinite(payout) || payout < 1.01) return json(res, 400, { error: 'Bet/payout tidak valid.' });
      if (maxLiveBet > 0 && bet > maxLiveBet) return json(res, 400, { error: `Bet melebihi batas ${maxLiveBet}.` });
      if (maxSessionLoss > 0 && s.sessionLoss >= maxSessionLoss) return json(res, 409, { error: 'Batas loss sesi tercapai.' });
      const result = await cg(`/placebet/${encodeURIComponent(s.coin)}/${encodeURIComponent(s.apiKey)}`, {
        method: 'POST',
        body: JSON.stringify({ Bet: Number(bet.toFixed(8)), Payout: payout, UnderOver: Boolean(i.UnderOver), ClientSeed: crypto.randomBytes(16).toString('hex') })
      });
      const profit = Number(result.Profit || 0);
      s.sessionLoss += Math.max(0, -profit);
      s.rolls++;
      return json(res, 200, { result, risk: { sessionLoss: s.sessionLoss, rolls: s.rolls } });
    }
    const requested = decodeURIComponent(url.pathname);
    const file = path.normalize(path.join(root, requested === '/' ? '/index.html' : requested));
    if (!file.startsWith(root)) { res.writeHead(403); return res.end('Forbidden'); }
    fs.readFile(file, (e, data) => {
      if (e) { res.writeHead(404); return res.end('Not found'); }
      res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
      res.end(data);
    });
  } catch (e) {
    console.error(e);
    json(res, 502, { error: e.message || 'Crypto.Games request failed' });
  }
});

