import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const outDir = process.argv[2] || '/tmp/icons';
fs.mkdirSync(outDir, { recursive: true });

const CRC_TABLE = new Uint32Array(256);
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  CRC_TABLE[n] = c >>> 0;
}
function crc32(buf) {
  let c = 0xffffffff;
  for (const byte of buf) c = CRC_TABLE[(c ^ byte) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const typeBuf = Buffer.from(type, 'ascii');
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])));
  return Buffer.concat([len, typeBuf, data, crc]);
}
function png(width, height, pixels) {
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    const row = y * (width * 4 + 1);
    raw[row] = 0;
    pixels.copy(raw, row + 1, y * width * 4, (y + 1) * width * 4);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ]);
}

function hex(value) {
  return [parseInt(value.slice(1, 3), 16), parseInt(value.slice(3, 5), 16), parseInt(value.slice(5, 7), 16)];
}
const GOLD = hex('#ffc928');
const GOLD_DARK = hex('#c89512');
const INK = hex('#171717');
const BG_TOP = hex('#303030');
const BG_BOTTOM = hex('#101010');

function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function roundedRect(x, y, left, top, right, bottom, radius) {
  const cx = Math.min(Math.max(x, left + radius), right - radius);
  const cy = Math.min(Math.max(y, top + radius), bottom - radius);
  const dx = x - cx;
  const dy = y - cy;
  return dx * dx + dy * dy <= radius * radius;
}
function circle(x, y, cx, cy, r) {
  return (x - cx) ** 2 + (y - cy) ** 2 <= r * r;
}

function draw(size, { maskable = false } = {}) {
  const scale = 4;
  const big = size * scale;
  const pixels = Buffer.alloc(size * size * 4);
  const outerInset = maskable ? 0 : big * 0.045;
  const outerRadius = maskable ? 0 : big * 0.225;
  const dieInset = maskable ? big * 0.235 : big * 0.185;
  const dieRadius = big * 0.145;
  const pipRadius = big * (maskable ? 0.043 : 0.052);
  const pipPositions = [
    [0.28, 0.28], [0.72, 0.28],
    [0.5, 0.5],
    [0.28, 0.72], [0.72, 0.72]
  ];
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0, g = 0, b = 0, a = 0;
      for (let sy = 0; sy < scale; sy++) {
        for (let sx = 0; sx < scale; sx++) {
          const x = px * scale + sx + 0.5;
          const y = py * scale + sy + 0.5;
          let sr = 0, sg = 0, sb = 0, sa = 0;
          const inOuter = roundedRect(x, y, outerInset, outerInset, big - outerInset, big - outerInset, outerRadius);
          if (inOuter) {
            const t = Math.min(1, Math.max(0, (y - outerInset) / (big - outerInset * 2)));
            const bg = mix(BG_TOP, BG_BOTTOM, t);
            sr = bg[0]; sg = bg[1]; sb = bg[2]; sa = 255;
            // soft gold glow behind the die
            const gx = (x - big / 2) / (big * 0.52);
            const gy = (y - big / 2) / (big * 0.52);
            const glow = Math.max(0, 1 - Math.sqrt(gx * gx + gy * gy));
            sr = sr + (GOLD[0] - sr) * glow * 0.16;
            sg = sg + (GOLD[1] - sg) * glow * 0.13;
            sb = sb + (GOLD[2] - sb) * glow * 0.04;
          }
          const dieLeft = dieInset;
          const dieRight = big - dieInset;
          if (roundedRect(x, y, dieLeft, dieTop(dieInset), dieRight, big - dieInset, dieRadius)) {
            const t = Math.min(1, Math.max(0, (y - dieInset) / (big - dieInset * 2)));
            const face = mix(GOLD, GOLD_DARK, t * 0.55);
            sr = face[0]; sg = face[1]; sb = face[2]; sa = 255;
          }
          const faceSize = dieRight - dieLeft;
          for (const [fx, fy] of pipPositions) {
            if (circle(x, y, dieLeft + faceSize * fx, dieInset + faceSize * fy, pipRadius)) {
              sr = INK[0]; sg = INK[1]; sb = INK[2]; sa = 255;
            }
          }
          r += sr * (sa / 255); g += sg * (sa / 255); b += sb * (sa / 255); a += sa;
        }
      }
      const total = scale * scale;
      const i = (py * size + px) * 4;
      const alpha = a / total;
      pixels[i] = Math.round(alpha > 0 ? (r / total) * 255 / (alpha / 255) : 0);
      pixels[i + 1] = Math.round(alpha > 0 ? (g / total) * 255 / (alpha / 255) : 0);
      pixels[i + 2] = Math.round(alpha > 0 ? (b / total) * 255 / (alpha / 255) : 0);
      pixels[i + 3] = Math.round(alpha);
    }
  }
  return png(size, size, pixels);
}

function dieTop(inset) {
  return inset;
}

const jobs = [
  ['icon-192.png', 192, {}],
  ['icon-512.png', 512, {}],
  ['icon-maskable-512.png', 512, { maskable: true }],
  ['apple-touch-icon.png', 180, {}],
  ['favicon-32.png', 32, {}]
];
for (const [name, size, options] of jobs) {
  fs.writeFileSync(path.join(outDir, name), draw(size, options));
  console.log('wrote', path.join(outDir, name));
}

